// Motor de Veredictos de Ciberseguridad
// Input: Datos mergeados de OpenAI + VirusTotal

const input = $input.all();

// Extraer datos de OpenAI (primer elemento)
const aiResponse = input[0].json.choices?.[0]?.message?.content || '';

// Extraer datos de VirusTotal (segundo elemento)
const vtData = input[1].json.data?.attributes || {};

// Datos de la alerta original
const alertData = $('Edit Fields').first().json;

// === ANÁLISIS DE THREAT INTELLIGENCE ===
const vtStats = vtData.last_analysis_stats || {};
const maliciousCount = vtStats.malicious || 0;
const suspiciousCount = vtStats.suspicious || 0;
const reputation = vtData.reputation || 0;

// Extraer información del país
const country = vtData.country || 'UNKNOWN';
const asn = vtData.asn || 0;
const network = vtData.network || 'UNKNOWN';

// === CÁLCULO DE RISK SCORE ===
function calculateRiskScore() {
  let score = 0;

  // 1. Severidad de la alerta (0-30 puntos)
  switch(alertData.severity?.toLowerCase()) {
    case 'critical':
      score += 30;
      break;
    case 'high':
      score += 20;
      break;
    case 'medium':
      score += 10;
      break;
    case 'low':
      score += 5;
      break;
  }

  // 2. VirusTotal - Detecciones maliciosas (0-40 puntos)
  score += Math.min(maliciousCount * 4, 40);

  // 3. VirusTotal - Detecciones sospechosas (0-20 puntos)
  score += Math.min(suspiciousCount * 2, 20);

  // 4. Reputación negativa (0-10 puntos)
  if (reputation < -50) score += 10;
  else if (reputation < 0) score += 5;

  // 5. Análisis de la IA
  const aiLower = aiResponse.toLowerCase();
  if (aiLower.includes('critical') || aiLower.includes('immediate')) score += 10;
  if (aiLower.includes('backdoor') || aiLower.includes('exploit')) score += 15;
  if (aiLower.includes('malicious')) score += 10;

  return Math.min(Math.round(score), 100);
}

// === DETERMINACIÓN DEL VEREDICTO ===
function determineVerdict(riskScore) {
  // BLOCK: Amenaza crítica inmediata
  if (riskScore >= 75) return 'BLOCK';

  // QUARANTINE: Amenaza alta, requiere aislamiento
  if (riskScore >= 50) return 'QUARANTINE';

  // INVESTIGATE: Comportamiento sospechoso
  if (riskScore >= 30) return 'INVESTIGATE';

  // MONITOR: Riesgo bajo, solo observar
  if (riskScore >= 15) return 'MONITOR';

  // ALLOW: Sin amenaza detectada
  return 'ALLOW';
}

// === ACCIONES RECOMENDADAS ===
function getRecommendedActions(verdict, riskScore) {
  const actions = [];

  switch(verdict) {
    case 'BLOCK':
      actions.push('Bloquear IP inmediatamente en firewall');
      actions.push('Aislar sistemas afectados de la red');
      actions.push('Iniciar investigación forense');
      actions.push('Notificar al equipo SOC inmediatamente');
      if (maliciousCount > 5) {
        actions.push('Buscar IOCs relacionados en toda la red');
      }
      break;

    case 'QUARANTINE':
      actions.push('Mover sistemas afectados a red de cuarentena');
      actions.push('Limitar acceso de la IP');
      actions.push('Analizar logs de acceso detalladamente');
      actions.push('Verificar lateral movement');
      break;

    case 'INVESTIGATE':
      actions.push('Revisar logs del sistema afectado');
      actions.push('Aumentar nivel de monitoreo para esta IP');
      actions.push('Correlacionar con otros eventos de seguridad');
      actions.push('Verificar si hay patrones de ataque');
      break;

    case 'MONITOR':
      actions.push('Continuar monitoreo pasivo');
      actions.push('Registrar evento para análisis de tendencias');
      actions.push('No se requiere acción inmediata');
      break;

    case 'ALLOW':
      actions.push('Sin amenaza detectada');
      actions.push('Registrar como falso positivo potencial');
      break;
  }

  return actions;
}

// === EXTRACCIÓN DE IOCs ===
function extractIOCs() {
  const iocs = {
    ip_address: alertData.ip_address,
    country: country,
    asn: asn,
    network: network,
    user_agent: alertData.user_agent || 'N/A',
    attack_type: alertData.type,
    timestamp: alertData.timestamp
  };

  // Intentar extraer más IOCs del análisis de IA
  const ipRegex = /\b(?:\d{1,3}\.){3}\d{1,3}\b/g;
  const hashRegex = /\b[a-fA-F0-9]{32,64}\b/g;

  const ipsFound = aiResponse.match(ipRegex) || [];
  const hashesFound = aiResponse.match(hashRegex) || [];

  if (ipsFound.length > 0) iocs.related_ips = [...new Set(ipsFound)];
  if (hashesFound.length > 0) iocs.file_hashes = [...new Set(hashesFound)];

  return iocs;
}

// === GENERAR RESUMEN EJECUTIVO ===
function generateExecutiveSummary(verdict, riskScore) {
  const severity = alertData.severity?.toUpperCase() || 'UNKNOWN';

  let summary = `🚨 SECURITY ALERT - ${severity}\n\n`;
  summary += `Veredicto: ${verdict}\n`;
  summary += `Risk Score: ${riskScore}/100\n`;
  summary += `IP: ${alertData.ip_address} (${country})\n`;
  summary += `Tipo de Ataque: ${alertData.type}\n\n`;

  summary += `📊 VirusTotal Analysis:\n`;
  summary += `- Detecciones Maliciosas: ${maliciousCount}/95\n`;
  summary += `- Detecciones Sospechosas: ${suspiciousCount}/95\n`;
  summary += `- Reputación: ${reputation}\n\n`;

  summary += `🤖 IA Analysis Summary:\n`;
  const aiLines = aiResponse.split('\n').slice(0, 5).join('\n');
  summary += aiLines + '\n';

  return summary;
}

// === CALCULAR TODO ===
const riskScore = calculateRiskScore();
const verdict = determineVerdict(riskScore);
const actions = getRecommendedActions(verdict, riskScore);
const iocs = extractIOCs();
const executiveSummary = generateExecutiveSummary(verdict, riskScore);

// === GENERAR REPORTE FINAL ===
const finalReport = {
  // Metadata
  report_id: `SEC-${Date.now()}`,
  timestamp: new Date().toISOString(),

  // Veredicto
  verdict: verdict,
  risk_score: riskScore,
  confidence: maliciousCount > 0 ? 'HIGH' : 'MEDIUM',

  // Alert original
  alert: {
    type: alertData.type,
    severity: alertData.severity,
    ip: alertData.ip_address,
    timestamp: alertData.timestamp,
    details: alertData.details
  },

  // Threat Intelligence
  threat_intelligence: {
    virustotal: {
      malicious_detections: maliciousCount,
      suspicious_detections: suspiciousCount,
      total_scans: 95,
      reputation: reputation,
      country: country,
      asn: asn,
      network: network
    }
  },

  // Análisis de IA
  ai_analysis: {
    full_report: aiResponse,
    summary: aiResponse.split('\n')[0]
  },

  // IOCs
  indicators_of_compromise: iocs,

  // Acciones recomendadas
  recommended_actions: actions,

  // Resumen ejecutivo
  executive_summary: executiveSummary,

  // Prioridad
  priority: riskScore >= 75 ? 'P1-CRITICAL' : 
            riskScore >= 50 ? 'P2-HIGH' :
            riskScore >= 30 ? 'P3-MEDIUM' : 'P4-LOW',

  // Estado
  status: 'PENDING_REVIEW',

  // Tags para búsqueda
  tags: [
    verdict,
    alertData.severity,
    alertData.type,
    country,
    `risk_${riskScore}`
  ]
};

// === OUTPUT ===
return {
  json: finalReport
};
